export const source="let imageLiteralCalls:number=0;class LiteralFactory{make:()=>Image;paint:(image:Image)=>void;constructor(){this.make=()=>{imageLiteralCalls+=1;return img`1 .\n. 2`};this.paint=(image:Image)=>{image.setPixel(0,0,7);image.setPixel(-1,0,9)}}}let imageLiteralFactory=new LiteralFactory();let imageLiteralFirst=imageLiteralFactory.make();let imageLiteralSecond=imageLiteralFactory.make();let imageLiteralAlias=imageLiteralFirst;imageLiteralFactory.paint(imageLiteralAlias);let imageLiteralThird=imageLiteralFactory.make();let imageLiteralChanged:number=imageLiteralFirst.getPixel(0,0);let imageLiteralOriginal:number=imageLiteralSecond.getPixel(0,0);let imageLiteralLater:number=imageLiteralThird.getPixel(0,0);let imageLiteralOutside:number=imageLiteralFirst.getPixel(-1,0);let imageLiteralAliasSame:boolean=imageLiteralAlias===imageLiteralFirst;let imageLiteralFresh:boolean=imageLiteralFirst!==imageLiteralSecond;let imageLiteralLaterFresh:boolean=imageLiteralSecond!==imageLiteralThird;let imageLiteralScore:number=imageLiteralChanged+imageLiteralOriginal+imageLiteralLater+imageLiteralOutside+imageLiteralCalls;if(imageLiteralAliasSame){imageLiteralScore+=1}if(imageLiteralFresh){imageLiteralScore+=2}if(imageLiteralLaterFresh){imageLiteralScore+=4}info.setScore(imageLiteralScore);";
